<?php
declare(strict_types=1);
namespace Liberu\ControlPanel\Kubernetes\Actions;
use Illuminate\Database\Eloquent\Model; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class RegisterKubernetesAsset { public function execute(array $a):Model { $kind=(string)($a['kind']??''); $map=['node'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesNode::class,'namespace'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesNamespace::class,'rbac'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesRbacBinding::class,'workload'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesWorkload::class,'ingress'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesIngress::class,'helm'=>\Liberu\ControlPanel\Kubernetes\Models\HelmRelease::class,'storage'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesStorageClaim::class,'autoscaling'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesAutoscaler::class,'upgrade'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesUpgrade::class,'cluster-view'=>\Liberu\ControlPanel\Kubernetes\Models\KubernetesClusterView::class]; if(!isset($map[$kind]))throw ValidationException::withMessages(['kind'=>'Unsupported Kubernetes asset.']); $a['id']=$a['id']??(string)Str::uuid();$a['team_id']=$a['team_id']??null; if($kind==='workload'){$a['kind']=$a['workload_kind']??'Deployment';}else{unset($a['kind']);}return $map[$kind]::query()->create($a); } }
